import sys

def solve(inp):
    tokens = inp.strip().split()
    if not tokens: return ''
    n = int(tokens[0])
    return '\n'.join(' ' * (n - i) + ''.join(chr(65 + n - 1 - j) for j in range(i)) for i in range(n, 0, -1))


def main():
    s = sys.stdin.read()
    if s.strip():
        print(solve(s))

if __name__ == '__main__':
    main()

code.JavaScript:
const fs = require('fs');
function solve(inp) {
    const tokens = inp.trim().split(/\s+/);
    if (!tokens || tokens.length === 0 || tokens[0] === '') return '';
    const n = parseInt(tokens[0], 10);
    const res = [];
    for (let i = n; i >= 1; i--) {
        let s = '';
        for (let j = 0; j < i; j++) s += String.fromCharCode(65 + n - 1 - j);
        res.push(' '.repeat(n - i) + s);
    }
    return res.join('\n');
}
function main() {
    const s = fs.readFileSync(0, 'utf-8').trim();
    if (s.length > 0) console.log(solve(s));
}
main();

